"use client";

import * as React from "react";
import styles from "../styles/stat-card.module.css";

export interface StatCardProps {
  /** Metric name shown at the top of the card */
  title?: string;
  /** Final value the number counts up to */
  value?: number;
  /** Text before the number (e.g. "$") */
  prefix?: string;
  /** Text after the number (e.g. "%", "ms") */
  suffix?: string;
  /** Decimal places shown */
  decimals?: number;
  /** Change versus the previous period, in percent (negative = down) */
  delta?: number;
  /** Text after the delta badge */
  deltaLabel?: string;
  /** Treat a decrease as good (e.g. churn, latency) — flips the delta colors */
  invertDelta?: boolean;
  /** Sparkline data points (oldest first) */
  data?: number[];
  /** Show the sparkline */
  showSparkline?: boolean;
  /** Sparkline / accent color */
  accentColor?: string;
  /** Count-up and draw-in duration in milliseconds (0 = instant) */
  duration?: number;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_DATA = [32, 38, 35, 44, 41, 49, 47, 55, 52, 61, 58, 68];
const W = 280;
const H = 64;

function format(n: number, decimals: number) {
  return n.toLocaleString("en-US", { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

export function StatCard({
  title = "Monthly revenue",
  value = 48294,
  prefix = "$",
  suffix = "",
  decimals = 0,
  delta = 12.4,
  deltaLabel = "vs last month",
  invertDelta = false,
  data = DEFAULT_DATA,
  showSparkline = true,
  accentColor = "#6366f1",
  duration = 1400,
  className = "",
  style,
}: StatCardProps) {
  const id = React.useId().replace(/:/g, "");
  const dec = Math.max(0, Math.min(4, Math.floor(decimals)));
  const [shown, setShown] = React.useState(0);
  const [reduce, setReduce] = React.useState(false);

  React.useEffect(() => {
    const r = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    setReduce(r);
    if (r || duration <= 0) {
      setShown(value);
      return;
    }
    let raf = 0;
    let start = 0;
    const tick = (now: number) => {
      if (!start) start = now;
      const t = Math.min(1, (now - start) / duration);
      setShown(value * (1 - Math.pow(1 - t, 4)));
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [value, duration]);

  const up = delta >= 0;
  const good = invertDelta ? !up : up;
  const pts = data.length > 1 ? data : [0, 0];
  const min = Math.min(...pts);
  const max = Math.max(...pts);
  const span = max - min || 1;
  const coords = pts.map((v, i) => [8 + (i / (pts.length - 1)) * (W - 16), H - 6 - ((v - min) / span) * (H - 12)] as const);
  const line = coords.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
  const area = `${line} L${W - 8} ${H} L8 ${H} Z`;
  const last = coords[coords.length - 1] ?? [W, H / 2];
  const final = `${prefix}${format(value, dec)}${suffix}`;

  return (
    <section
      aria-label={title}
      className={`${styles.root} ${className}`.trim()}
      data-animate={!reduce && duration > 0 ? "" : undefined}
      style={{ "--mf-stc-accent": accentColor, "--mf-stc-dur": `${Math.max(0, duration)}ms`, ...style } as React.CSSProperties}
    >
      <div className={styles.head}>
        <span className={styles.title}>{title}</span>
        <span className={styles.badge} data-good={good ? "" : undefined}>
          <svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.75" strokeLinecap="round" strokeLinejoin="round">
            {up ? <path d="M7 17 17 7M9 7h8v8" /> : <path d="M7 7l10 10M17 9v8H9" />}
          </svg>
          <span className={styles.srOnly}>{up ? "Up" : "Down"}</span>
          {Math.abs(delta).toFixed(1)}%
        </span>
      </div>
      <p className={styles.value}>
        <span className={styles.srOnly}>{final}</span>
        <span aria-hidden="true">
          {prefix}
          {format(shown, dec)}
          {suffix}
        </span>
      </p>
      {deltaLabel && <p className={styles.sub}>{`${up ? "+" : "−"}${Math.abs(delta).toFixed(1)}% ${deltaLabel}`}</p>}
      {showSparkline && (
        <div className={styles.sparkWrap}>
          <svg
            role="img"
            aria-label={`Trend over ${pts.length} periods, from ${format(pts[0] ?? 0, 0)} to ${format(pts[pts.length - 1] ?? 0, 0)}`}
            className={styles.spark}
            viewBox={`0 0 ${W} ${H}`}
          >
            <defs>
              <linearGradient id={`${id}-fill`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={accentColor} stopOpacity="0.32" />
                <stop offset="100%" stopColor={accentColor} stopOpacity="0" />
              </linearGradient>
            </defs>
            <path className={styles.area} d={area} fill={`url(#${id}-fill)`} />
            <path className={styles.line} d={line} pathLength={1} fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <span
            aria-hidden="true"
            className={styles.endDot}
            style={{ left: `${(last[0] / W) * 100}%`, top: `${(last[1] / H) * 100}%` } as React.CSSProperties}
          />
        </div>
      )}
    </section>
  );
}

.root {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 21rem;
  padding: 1.25rem 1.25rem 0;
  overflow: hidden;
  border-radius: 0.75rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12), 0 12px 32px -16px color-mix(in srgb, var(--mf-stc-accent, #6366f1) 35%, transparent);
  transition: border-color 180ms ease, transform 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

.root:hover {
  border-color: var(--mf-border-strong, #52525b);
  transform: translateY(-2px);
}

.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.title {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--mf-muted, #a1a1aa);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  height: 1.375rem;
  padding: 0 0.5rem;
  border-radius: 999px;
  background-color: color-mix(in srgb, #ef4444 15%, transparent);
  color: #ef4444;
  font-size: 0.75rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.badge[data-good] {
  background-color: color-mix(in srgb, #22c55e 15%, transparent);
  color: #22c55e;
}

.value {
  margin: 0.5rem 0 0;
  font-size: 2.125rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}

.sub {
  margin: 0.25rem 0 0;
  font-size: 0.8125rem;
  color: var(--mf-subtle, #71717a);
}

.sparkWrap {
  position: relative;
  margin: 0.75rem -1.25rem 0;
}

.spark {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

.line {
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
}

.root[data-animate] .line {
  animation: mf-stc-draw var(--mf-stc-dur, 1400ms) cubic-bezier(0.65, 0, 0.35, 1) both;
}

.root[data-animate] .area {
  animation: mf-stc-fade var(--mf-stc-dur, 1400ms) ease-out both;
}

.endDot {
  position: absolute;
  width: 0.5rem;
  height: 0.5rem;
  margin: -0.25rem 0 0 -0.25rem;
  border-radius: 999px;
  background-color: var(--mf-stc-accent, #6366f1);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--mf-stc-accent, #6366f1) 30%, transparent);
}

.root[data-animate] .endDot {
  animation: mf-stc-pop 360ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
  animation-delay: var(--mf-stc-dur, 1400ms);
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@keyframes mf-stc-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes mf-stc-fade {
  0%,
  35% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

@keyframes mf-stc-pop {
  from {
    opacity: 0;
    transform: scale(0);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .root {
    transition: none;
  }
  .root:hover {
    transform: none;
  }
  .root[data-animate] .line,
  .root[data-animate] .area,
  .root[data-animate] .endDot {
    animation: none;
  }
}

