"use client";

import { useEffect, useState } from "react";

const data = [32, 38, 35, 44, 41, 49, 47, 55, 52, 61, 58, 68];

export function StatCardTailwind({ title = "Monthly revenue", value = 48294, delta = 12.4 }) {
  const [n, setN] = useState(0);
  useEffect(() => {
    let raf = 0, t0 = 0;
    const tick = (t: number) => { t0 ||= t; const p = Math.min(1, (t - t0) / 1400); setN(value * (1 - (1 - p) ** 4)); if (p < 1) raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [value]);
  const min = Math.min(...data), max = Math.max(...data);
  const d = data.map((v, i) => `${i ? "L" : "M"}${8 + (i / (data.length - 1)) * 264} ${58 - ((v - min) / (max - min)) * 52}`).join(" ");
  const up = delta >= 0;
  return (
    <section aria-label={title} className="w-full max-w-xs overflow-hidden rounded-xl border border-zinc-800 bg-zinc-900 px-5 pt-5 text-zinc-100">
      <div className="flex items-center justify-between">
        <span className="text-sm text-zinc-400">{title}</span>
        <span className={`rounded-full px-2 py-0.5 text-xs font-semibold ${up ? "bg-emerald-500/15 text-emerald-500" : "bg-red-500/15 text-red-500"}`}>{up ? "↑" : "↓"} {Math.abs(delta)}%</span>
      </div>
      <p className="mt-2 text-3xl font-bold tabular-nums tracking-tight" aria-label={`$${value.toLocaleString("en-US")}`}>${Math.round(n).toLocaleString("en-US")}</p>
      <svg viewBox="0 0 280 64" className="-mx-5 mt-3 block w-[calc(100%+2.5rem)]" role="img" aria-label="Trend">
        <path d={d} pathLength={1} fill="none" stroke="#6366f1" strokeWidth={2} strokeLinecap="round" className="[stroke-dasharray:1] animate-[draw_1.4s_ease-in-out_both]" />
      </svg>
    </section>
  );
}
